import{_ as t,a as i}from"./chunks/EditCollection3.DJXc7XnK.js";import{_ as o,c as a,a2 as n,o as s}from"./chunks/framework.CoXjB5sU.js";const r="/assets/CreatePublishFormEmbargo.C8vr4mby.png",l="/assets/embargoed-collection.BAoL48al.png",c="/assets/LoginRequired.BepwXm9A.png",h="/assets/ReviewLinkLanding.YuiKwQcM.png",g="/assets/EditCollection4.DfnT6kDA.png",m="/assets/EditCollectionLifted.zguP9IES.png",y=JSON.parse('{"title":"Setting the embargo","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/publishing-calculations/embargo.md","filePath":"doc/guides/usage/publishing-calculations/embargo.md"}'),d={name:"doc/guides/usage/publishing-calculations/embargo.md"};function p(b,e,u,w,f,v){return s(),a("div",null,e[0]||(e[0]=[n('<h1 id="setting-the-embargo" tabindex="-1">Setting the embargo <a class="header-anchor" href="#setting-the-embargo" aria-label="Permalink to &quot;Setting the embargo&quot;">​</a></h1><p>Under some circumstances, ioChem-BD users need to restrict the access to elements published on the Browse module.</p><p>The most common situation is while publishing a manuscript in a journal and its supporting information needs to be accessed by the reviewers. In that case the published dataset has to be private to everyone but visible to a reduced number of users (the reviewers). To do so, check the <em>Embargo published elements, content restricted only to reviewers</em> option in <strong>Section 6: Publication Options</strong> of the publication form.</p><p><img src="'+r+'" alt="Publication options with the embargo checkbox"></p><p>With this option activated, published elements will be visible inside its collection in the Browse module...</p><p><img src="'+l+'" alt="Embargoed collection view"></p><p>...marked as <em>Under embargo</em>, but anonymous visitors who open one of its items only get a notice: the item appears in searches and navigation, while its detailed record stays hidden until the embargo is lifted.</p><p><img src="'+c+'" alt="Embargo notice of an embargoed item"></p><h2 id="accessing-the-embargoed-elements" tabindex="-1">Accessing the embargoed elements <a class="header-anchor" href="#accessing-the-embargoed-elements" aria-label="Permalink to &quot;Accessing the embargoed elements&quot;">​</a></h2><p>Embargoed collections generate a unique <strong>reviewer link</strong> that grants access to their content. It is displayed in the <em>Publication Resume</em> window right after publishing the embargoed content, and it should be shared with the collection reviewers.</p><p><img src="'+t+'" alt="Publication resume with the peer review access link"></p><p>Opening the reviewer link exchanges its key for temporary access and lands directly on the collection, unlocking the full content for the reviewer. A short guided tour (<em>Welcome to ioChem-BD</em>) shows the reviewer how to navigate the restricted content.</p><p><img src="'+h+'" alt="Reviewer link landing"></p><p>Using the reviewer link, reviewers can:</p><ul><li>read the full list of metadata fields,</li><li>display molecule geometries in the structure viewer,</li><li>view the HTML5 report,</li><li>download calculation related files.</li></ul><h2 id="managing-the-embargo" tabindex="-1">Managing the embargo <a class="header-anchor" href="#managing-the-embargo" aria-label="Permalink to &quot;Managing the embargo&quot;">​</a></h2><p>Users can retrieve the reviewer link anytime from the Create module by clicking the <strong>edit icon</strong> next to the published project in the workspace tree. This opens the <em>Edit published collection</em> page, where the <strong>Embargo</strong> section shows the reviewer link with a <strong>Copy link to clipboard</strong> button.</p><p><img src="'+i+'" alt="Embargo section with the reviewer link"></p><h2 id="lifting-the-embargo" tabindex="-1">Lifting the embargo <a class="header-anchor" href="#lifting-the-embargo" aria-label="Permalink to &quot;Lifting the embargo&quot;">​</a></h2><p>Once the content has been validated or reviewed, the embargo can be lifted on the same <em>Edit published collection</em> page using the <strong>Lift embargo on all collection items (go public)</strong> button, and confirming with <strong>Yes</strong>.</p><p><img src="'+g+'" alt="Lift embargo button"></p><p>Once the embargo is lifted, the embargo section on the edit page disappears and the reviewer links cease to work.</p><p><img src="'+m+'" alt="Edit page after lifting the embargo"></p>',23)]))}const E=o(d,[["render",p]]);export{y as __pageData,E as default};
